\begin{lemma}[Magnetization fixed by the equation of state]
\label{lem:IPhO2026Problems_problem_IPhO_2026_3_B_1:MagnetizationEqEosSolution}
\lean{IPhO2026.Problem3.B1.magnetization_eq_eos_solution}
