+\begin{lemma}[Angular-factor identity]
+\label{lem:IPhO2026Problems_problem_IPhO_2026_1_C_1:two_sin_sq_add_one_eq}
+\lean{IPhO2026.Problem1.C1.two_sin_sq_add_one_eq}
