+\begin{theorem}[Minimum angular frequency, forward branch]
+\label{thm:IPhO2026Problems_problem_IPhO_2026_1_C_1:minimum_angular_frequency_T1_C1}
+\lean{IPhO2026.Problem1.C1.minimum_angular_frequency_T1_C1}
