+\begin{theorem}[A.2 target: source work $dW_{\mathrm{emf}} = V H\,dB$]
+\label{thm:IPhO2026Problems_problem_IPhO_2026_3_A_2:work_emf_eq_V_mul_H_mul_dB}
+\lean{IPhO2026_3_A_2.work_emf_eq_V_mul_H_mul_dB}
