+\begin{lemma}[Evaluation of one isothermal work leg]
+\label{lem:IPhO2026Problems_problem_IPhO_2026_3_B_1:LegWorkIntegralEval}
+\lean{IPhO2026.Problem3.B1.leg_work_integral_eval}
